import 'package:flutter/material.dart';
class TacticalPitch extends StatelessWidget{const TacticalPitch({super.key,required this.entries});final List<dynamic> entries;@override Widget build(BuildContext c)=>AspectRatio(aspectRatio:.68,child:Container(decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),gradient:const LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Color(0xff16884f),Color(0xff0b6b3d)])),child:LayoutBuilder(builder:(c,b)=>Stack(children:[Positioned.fill(child:CustomPaint(painter:_PitchPainter())),...entries.map((e){final x=((e['x']??50) as num).toDouble()/100,y=((e['y']??50) as num).toDouble()/100;return Positioned(left:(b.maxWidth*x)-18,top:(b.maxHeight*y)-18,child:Tooltip(message:'${e['player']?['name']??e['player_name']??''}',child:CircleAvatar(radius:18,backgroundColor:Colors.white,foregroundColor:Colors.black,child:Text('${e['shirt_number']??''}',style:const TextStyle(fontWeight:FontWeight.w900)))));})]))));}
class ShotMap extends StatelessWidget{const ShotMap({super.key,required this.shots});final List<dynamic> shots;@override Widget build(BuildContext c)=>AspectRatio(aspectRatio:.68,child:Container(decoration:BoxDecoration(borderRadius:BorderRadius.circular(24),color:const Color(0xff0b6b3d)),child:LayoutBuilder(builder:(c,b)=>Stack(children:[Positioned.fill(child:CustomPaint(painter:_PitchPainter())),...shots.map((s){final x=((s['x']??50)as num).toDouble()/100,y=((s['y']??50)as num).toDouble()/100,out='${s['outcome']??''}',xg=((s['xg']??0)as num).toDouble();return Positioned(left:b.maxWidth*x-7,top:b.maxHeight*y-7,child:Tooltip(message:'${s['player']?['name']??''} • xG ${xg.toStringAsFixed(2)}',child:Container(width:14+12*xg,height:14+12*xg,decoration:BoxDecoration(shape:BoxShape.circle,color:out=='goal'?Colors.amber:Colors.white,border:Border.all(color:Colors.black,width:2)))));})]))));}
class MomentumChart extends StatelessWidget{const MomentumChart({super.key,required this.points});final List<dynamic> points;@override Widget build(BuildContext c)=>SizedBox(height:140,child:Row(crossAxisAlignment:CrossAxisAlignment.center,children:points.map((p){final double v=((p['value']??0)as num).toDouble().clamp(-100.0,100.0).toDouble();return Expanded(child:Align(alignment:v>=0?Alignment.bottomCenter:Alignment.topCenter,child:Container(height:4+v.abs(),margin:const EdgeInsets.symmetric(horizontal:1),decoration:BoxDecoration(color:v>=0?Theme.of(c).colorScheme.primary:Theme.of(c).colorScheme.error,borderRadius:BorderRadius.circular(6)))));}).toList()));}
class _PitchPainter extends CustomPainter{@override void paint(Canvas c,Size s){final p=Paint()..color=Colors.white.withValues(alpha: .55)..style=PaintingStyle.stroke..strokeWidth=1.5;final r=Rect.fromLTWH(s.width*.08,s.height*.05,s.width*.84,s.height*.90);c.drawRect(r,p);c.drawLine(Offset(r.left,r.center.dy),Offset(r.right,r.center.dy),p);c.drawCircle(r.center,Math.min(s.width,s.height)*.10,p);c.drawRect(Rect.fromCenter(center:Offset(r.center.dx,r.top),width:s.width*.38,height:s.height*.14),p);c.drawRect(Rect.fromCenter(center:Offset(r.center.dx,r.bottom),width:s.width*.38,height:s.height*.14),p);}@override bool shouldRepaint(covariant CustomPainter oldDelegate)=>false;}
class Math{static double min(double a,double b)=>a<b?a:b;}
